/** Card / PayPal brand marks for checkout (same paths as Mentorías payment methods). */
export function PaymentCardBrandLogos({
  className,
  compact = false,
}: {
  className?: string;
  compact?: boolean;
}) {
  return (
    <span
      className={[
        "payment-card-brands",
        compact ? "payment-card-brands--compact" : "",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      aria-hidden="true"
    >
      <svg
        className="payment-card-brands__visa"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        role="img"
        aria-label="Visa"
      >
        <path
          fill="#1434CB"
          d="M9.112 8.262L5.97 15.758H3.92L2.374 9.775c-.094-.368-.175-.503-.461-.658C1.447 8.864.677 8.627 0 8.479l.046-.217h3.3a.904.904 0 0 1 .894.764l.817 4.338l2.018-5.102zm8.033 5.049c.008-1.979-2.736-2.088-2.717-2.972c.006-.269.262-.555.822-.628a3.66 3.66 0 0 1 1.913.336l.34-1.59a5.2 5.2 0 0 0-1.814-.333c-1.917 0-3.266 1.02-3.278 2.479c-.012 1.079.963 1.68 1.698 2.04c.756.367 1.01.603 1.006.931c-.005.504-.602.725-1.16.734c-.975.015-1.54-.263-1.992-.473l-.351 1.642c.453.208 1.289.39 2.156.398c2.037 0 3.37-1.006 3.377-2.564m5.061 2.447H24l-1.565-7.496h-1.656a.88.88 0 0 0-.826.55l-2.909 6.946h2.036l.405-1.12h2.488zm-2.163-2.656l1.02-2.815l.588 2.815zm-8.16-4.84l-1.603 7.496H8.34l1.605-7.496z"
        />
      </svg>
      <svg
        className="payment-card-brands__mc"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        role="img"
        aria-label="Mastercard"
      >
        <circle cx="8.5" cy="12" r="6.5" fill="#EB001B" />
        <circle cx="15.5" cy="12" r="6.5" fill="#F79E1B" />
        <path
          fill="#FF5F00"
          d="M12 7.05a6.5 6.5 0 0 0 0 9.9 6.5 6.5 0 0 0 0-9.9z"
        />
      </svg>
      <svg
        className="payment-card-brands__amex"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 32 20"
        role="img"
        aria-label="American Express"
      >
        <rect width="32" height="20" rx="2" fill="#2E77BC" />
        <text
          x="16"
          y="13.5"
          textAnchor="middle"
          fill="#fff"
          fontFamily="Arial, Helvetica, sans-serif"
          fontSize="7"
          fontWeight="700"
          letterSpacing="0.4"
        >
          AMEX
        </text>
      </svg>
    </span>
  );
}

